  cursor: pointer;
  transition: background-color 0.3s, color 0.3s, border-color 0.3s; height: 52px; padding: 0 32px; border: none; background: hsl(var(--ink-foreground)); color: hsl(var(--ink)); font-size: 0.875rem; } .ds-btn-light:hover { background: #ffffff; } .ds-btn-light:focus-visible { outline: 2px solid hsl(var(--gold));
  outline-offset: 3px; } .ds-btn-light:disabled { opacity: 0.5; }

.ds-btn-ink { display: inline-flex;
